window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[134]={"id":"134","numero":134,"titre":"Bases neurophysiologiques et évaluation d'une douleur aiguë et chronique","objectifs":[{"id":"134-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition OMS de la douleur","contenu":"<p>La <span class=\"kw-def\">douleur</span> est définie par l'IASP (définition reprise par l'OMS) comme une <strong>« expérience désagréable, sensorielle et émotionnelle, associée ou ressemblant à ce qui est associé à une <span class=\"kw-clinique\">lésion</span> tissulaire réelle ou potentielle »</strong>.</p>\n      <ul>\n        <li>La douleur est <strong>toujours une expérience personnelle</strong>, influencée à des degrés divers par des facteurs <span class=\"kw-def\">biologiques</span>, <span class=\"kw-def\">psychologiques</span> et <span class=\"kw-def\">sociaux</span>.</li>\n        <li><span class=\"kw-def\">Douleur</span> et <span class=\"kw-def\">nociception</span> sont des phénomènes <strong>différents</strong> : la douleur ne se résume pas à l'activité des neurones sensoriels.</li>\n        <li>Le rapport que fait une personne de son expérience douloureuse <strong>doit être respecté</strong>.</li>\n        <li>La douleur a généralement un rôle <strong>adaptatif</strong>, mais peut avoir des effets négatifs sur la fonction et le bien-être.</li>\n      </ul>\n      <div class=\"obj-callout\">📌 <strong>On ne cherche pas à objectiver la douleur</strong> pour la « confirmer » : il n'existe <span class=\"kw-alerte\">aucun biomarqueur de la douleur</span>. <span class=\"kw-clinique\">Les</span> conséquences physiologiques (<span class=\"kw-clinique\">tachycardie</span>) et l'activation des aires cérébrales en imagerie ne sont que <strong>partiellement corrélées</strong> à l'expérience vécue.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Trois notions à ne pas confondre</h4>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Notion</th><th>Définition</th><th>Formule</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Nociception</span></td><td>Système physiologique de détection des stimulations menaçant l'intégrité de l'organisme. Une <span class=\"kw-clinique\">lésion</span> tissulaire peut exister <strong>sans</strong> perception douloureuse.</td><td><em>« ça fait mal »</em></td></tr>\n          <tr><td><span class=\"kw-def\">Douleur</span></td><td>Expérience sensorielle <strong>et</strong> émotionnelle ; comporte une dimension psychologique, surtout lorsqu'elle est chronique.</td><td><em>« j'ai mal »</em></td></tr>\n          <tr><td><span class=\"kw-def\">Souffrance</span></td><td>Expérience plus globale, existentielle, qui peut être ou non associée à une douleur ressentie dans le corps.</td><td><em>« je suis mal »</em></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Anomalies de la perception douloureuse</h4>\n      <p>Deux notions sémiologiques, à toujours caractériser par la <strong>modalité de stimulation</strong> (mécanique, thermique, chimique) :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Terme</th><th>Définition</th><th>Contexte typique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Allodynie</span></td><td>Abaissement du seuil douloureux : un stimulus <strong>normalement non douloureux</strong> est perçu comme douloureux.</td><td>Surtout <span class=\"kw-etio\">douleurs neuropathiques</span></td></tr>\n          <tr><td><span class=\"kw-def\">Hyperalgésie</span></td><td>Perception douloureuse <strong>anormalement intense</strong> à un stimulus normalement douloureux.</td><td>Caractéristique des <span class=\"kw-etio\">douleurs par excès de nociception</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout warning\">⚠️ <strong>Piège classique.</strong> Douleur ≠ nociception : on peut avoir une <span class=\"kw-alerte\">lésion tissulaire sans douleur</span>, ou une <span class=\"kw-alerte\">douleur sans cause nociceptive identifiable</span> (douleurs psychogènes, nociplastiques).</div>","frequence":0},{"id":"134-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les bases neurophysiologiques de la douleur","contenu":"<p>La <span class=\"kw-def\">physiopathologie</span> de la douleur s'articule autour de <strong>4 processus</strong> successifs :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Processus</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Transduction</span></td><td>Conversion de l'énergie d'un stimulus (mécanique, thermique, chimique) en énergie électrique par <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">nocicepteurs</span>.</td></tr>\n          <tr><td><span class=\"kw-def\">Transmission</span></td><td>Acheminement du signal vers la moelle épinière puis le cerveau.</td></tr>\n          <tr><td><span class=\"kw-def\">Perception</span></td><td>Intégration des signaux par <span class=\"kw-clinique\">les</span> structures de la douleur (<span class=\"kw-def\">thalamus</span>, <span class=\"kw-def\">cortex somesthésique</span> primaire).</td></tr>\n          <tr><td><span class=\"kw-def\">Modulation</span></td><td>Régulation par <span class=\"kw-clinique\">les</span> voies descendantes inhibitrices et facilitatrices ; explique l'effet de l'attention, de la distraction et de l'anticipation.</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Récepteurs et fibres périphériques</h4>\n      <p>La douleur par excès de nociception naît à la périphérie sur <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">nocicepteurs</span> = <strong>terminaisons nerveuses libres</strong> des fibres sensorielles de <strong>fin <span class=\"kw-clinique\">diamètre</span></strong>, qui ne répondent qu'à des stimulations d'intensité nociceptive élevée.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Fibre</th><th>Caractéristiques</th><th>Sensation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Fibres Aδ</span> (≈ <span class=\"kw-chiffre\">20 %</span>)</td><td>Fin <span class=\"kw-clinique\">diamètre</span>, <strong>myélinisées</strong> ; transmission <strong>rapide</strong> ; prolongent <span class=\"kw-clinique\">les</span> mécanonocicepteurs.</td><td>1ʳᵉ douleur, brève, type <span class=\"kw-clinique\">piqûre</span></td></tr>\n          <tr><td><span class=\"kw-def\">Fibres C</span> (≈ <span class=\"kw-chiffre\">80 %</span>)</td><td>Fin <span class=\"kw-clinique\">diamètre</span>, <strong>non myélinisées</strong> ; transmission <strong>lente</strong> ; prolongent <span class=\"kw-clinique\">les</span> nocicepteurs polymodaux.</td><td>2ᵉ douleur, retardée, type <span class=\"kw-clinique\">brûlure</span></td></tr>\n        </tbody>\n      </table>\n      <p>La coexistence de ces deux fibres explique le phénomène de <strong>double douleur</strong>. On distingue 3 classes de nocicepteurs selon le stimulus : <span class=\"kw-def\">mécanonocicepteurs</span>, <span class=\"kw-def\">thermonocicepteurs</span> (actifs <span class=\"kw-chiffre\">&lt; 10 °C</span> ou <span class=\"kw-chiffre\">&gt; 43 °C</span>) et <span class=\"kw-def\">chémonocicepteurs</span> ; <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">nocicepteurs polymodaux</span> répondent à plusieurs modalités.</p>\n      <p>À la périphérie, l'inflammation génère une « <strong>soupe <span class=\"kw-etio\">inflammatoire</span></strong> » :</p>\n      <ul>\n        <li>Substances <span class=\"kw-etio\">algogènes</span> (déclenchent l'influx douloureux) : <span class=\"kw-bio\">sérotonine</span>, <span class=\"kw-bio\">bradykinine</span>, ions <span class=\"kw-bio\">H⁺</span> et <span class=\"kw-bio\">K⁺</span>, <span class=\"kw-bio\">ATP</span>.</li>\n        <li>Substances <span class=\"kw-etio\">sensibilisatrices</span> (abaissent le seuil → <span class=\"kw-alerte\">hyperalgésie primaire</span>) : <span class=\"kw-bio\">prostaglandines</span>, <span class=\"kw-bio\">leucotriènes</span>, <span class=\"kw-bio\">histamine</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Relais spinal — corne dorsale</h4>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/134/coupe-moelle-epiniere-couches-rexed.png\" alt=\"Coupe transversale de moelle épinière : corne dorsale sensorielle, corne ventrale motrice, couches de Rexed I à X, cordons postérieur, latéral et antérieur\" loading=\"lazy\">\n        <figcaption>Coupe transversale de moelle épinière. La substance grise est divisée en 10 couches de Rexed : 6 dans la corne dorsale (sensorielle), 3 dans la corne ventrale (motrice), la couche X étant péri-épendymaire. <span class=\"kw-clinique\">Les</span> fibres nociceptives Aδ et C se terminent dans les couches superficielles I-II et profondes V-VI. Source : fiche source EDN item 134 (Bases neurophysiologiques de la douleur).</figcaption>\n      </figure>\n      <p><span class=\"kw-clinique\">Les</span> fibres nociceptives <span class=\"kw-def\">Aδ</span> et <span class=\"kw-def\">C</span> se terminent dans les <strong>couches superficielles I-II</strong> et <strong>profondes V-VI</strong> de la corne dorsale de la moelle ; les fibres non nociceptives de gros <span class=\"kw-clinique\">diamètre</span> <span class=\"kw-def\">Aα/Aβ</span> rejoignent les couches intermédiaires III-IV. Deux populations de neurones nociceptifs :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Neurone</th><th>Localisation</th><th>Réponse</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Nociceptif spécifique</span></td><td>Couche superficielle I (et II)</td><td>Stimulations de <strong>haute intensité</strong> uniquement</td></tr>\n          <tr><td><span class=\"kw-def\">Non spécifique</span> (WDR, à convergence)</td><td>Couches profondes V-VI</td><td>Stimulations de <strong>faible et haute intensité</strong> ; codent l'intensité</td></tr>\n        </tbody>\n      </table>\n      <p>La <strong>convergence viscéro-cutanée</strong> sur un même neurone WDR explique la <span class=\"kw-def\">douleur projetée / rapportée</span> (ex. : une douleur cardiaque ressentie dans le <span class=\"kw-clinique\">bras gauche</span>). Au niveau de la synapse, le <span class=\"kw-bio\">glutamate</span> et la <span class=\"kw-bio\">substance P</span> activent le <span class=\"kw-def\">récepteur NMDA</span> → entrée massive de Ca²⁺ → <span class=\"kw-alerte\">hyperalgésie secondaire</span> et plasticité neuronale.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Voies ascendantes et composantes</h4>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Faisceau</th><th>Projection</th><th>Composante</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Spino-thalamique latéral</span></td><td>Thalamus VPL → cortex somesthésique S1/S2</td><td><strong>Sensori-discriminative</strong> : intensité, durée, localisation, qualité</td></tr>\n          <tr><td><span class=\"kw-def\">Spino-réticulaire</span> (médial)</td><td>Tronc cérébral, cortex insulaire et cingulaire antérieur</td><td><strong>Motivo-affective / émotionnelle</strong> : tonalité désagréable</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Systèmes de contrôle de la douleur</h4>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Système</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Gate Control</span> (théorie du portillon)</td><td><span class=\"kw-clinique\">Les</span> fibres tactiles <span class=\"kw-def\">Aβ</span> activent des interneurones inhibiteurs spinaux et <strong>ferment le portillon</strong> aux messages nociceptifs. Base du réflexe « se frotter » et de la <span class=\"kw-ttt\">TENS</span> (neurostimulation électrique transcutanée).</td></tr>\n          <tr><td><span class=\"kw-def\">Récepteurs opioïdes / enképhalines</span></td><td>Riches dans <span class=\"kw-clinique\">les</span> couches superficielles de la moelle ; bloquent la libération des neuromédiateurs. Base de l'administration <strong>périmédullaire</strong> des opioïdes.</td></tr>\n          <tr><td><span class=\"kw-def\">Contrôle inhibiteur descendant</span></td><td>Issu du tronc cérébral, <span class=\"kw-bio\">sérotoninergique</span> et <span class=\"kw-bio\">noradrénergique</span> ; cible des antidépresseurs mixtes, du <span class=\"kw-ttt\">tramadol</span> et des agonistes α2.</td></tr>\n          <tr><td><span class=\"kw-def\">CIDN</span> (contrôles inhibiteurs diffus)</td><td>Boucle spino-bulbo-spinale sérotoninergique : « <strong>la douleur masque la douleur</strong> » (contre-irritation). Support neurophysiologique de l'acupuncture.</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sensibilisation centrale = douleur chronique</h4>\n      <p>Lorsque la douleur se prolonge, des mécanismes de <span class=\"kw-def\">sensibilisation</span> périphérique (inflammation) et surtout <strong>centrale</strong> (neuroplasticité) s'installent et pérennisent la douleur — véritable <span class=\"kw-alerte\">maladie des voies de la douleur</span>. Le <span class=\"kw-def\">récepteur NMDA</span> glutamatergique en est l'acteur clé : la <span class=\"kw-ttt\">kétamine</span>, antagoniste NMDA, est utilisée dans <span class=\"kw-clinique\">les</span> douleurs chroniques rebelles.</p>\n      <p>Enfin, la douleur intègre <strong>4 composantes</strong> : <span class=\"kw-def\">sensori-discriminative</span>, <span class=\"kw-def\">émotionnelle</span>, <span class=\"kw-def\">cognitive</span> et <span class=\"kw-def\">comportementale</span>.</p>\n      <div class=\"obj-callout warning\">⚠️ <strong>À retenir.</strong> La <span class=\"kw-def\">modulation</span> est la dernière étape du processus douloureux : attention, distraction et anticipation modifient réellement la perception — la douleur n'est jamais un signal « brut ».</div>","frequence":0},{"id":"134-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments del’interrogatoire d’un patient douloureux","contenu":"<p>L'interrogatoire d'un patient douloureux chronique suit une <strong>grille d'entretien semi-structuré</strong> en <strong>9 axes</strong>. Le <span class=\"kw-clinique\">retentissement</span> (anxiété, <span class=\"kw-def\">dépression</span>, troubles du sommeil, incapacité fonctionnelle et professionnelle) en est le fil rouge.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Axe</th><th>Éléments à explorer</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Ancienneté</span> de la douleur</td><td>Mode de début ; circonstances exactes (maladie, traumatisme, accident de travail) ; description de la douleur initiale ; prise en charge immédiate ; diagnostic initial.</td></tr>\n          <tr><td><span class=\"kw-def\">Profil évolutif</span></td><td>Installation de l'état douloureux persistant ; profil (douleur <span class=\"kw-clinique\">permanente</span>, <span class=\"kw-clinique\">récurrente</span>, <span class=\"kw-clinique\">intermittente</span>) ; degré de retentissement.</td></tr>\n          <tr><td><span class=\"kw-def\">Traitements</span></td><td>Traitements <span class=\"kw-etio\">médicamenteux</span> et non médicamenteux antérieurs et actuels ; doses et modes d'administration ; effets bénéfiques partiels, effets indésirables, raisons d'abandon.</td></tr>\n          <tr><td><span class=\"kw-def\">Antécédents</span></td><td>Familiaux ; personnels (médicaux, chirurgicaux, obstétricaux, <strong>psychiatriques</strong>) ; expériences douloureuses antérieures.</td></tr>\n          <tr><td><span class=\"kw-def\">Description</span> de la douleur actuelle</td><td><strong>Topographie</strong> ; <strong>type de sensation</strong> (<span class=\"kw-clinique\">brûlure</span>, <span class=\"kw-clinique\">décharge électrique</span>) ; <strong>intensité</strong> ; facteurs d'aggravation et de soulagement ; retentissement.</td></tr>\n          <tr><td><span class=\"kw-def\">Contexte</span> familial, psychosocial, médico-légal</td><td>Situation familiale et sociale ; statut professionnel et satisfaction au travail ; indemnisations, implications financières, procédures en cours.</td></tr>\n          <tr><td><span class=\"kw-def\">Facteurs cognitifs</span></td><td>Représentation de la maladie (peur d'une maladie évolutive) ; interprétation des avis médicaux.</td></tr>\n          <tr><td><span class=\"kw-def\">Facteurs comportementaux</span></td><td>Attitude vis-à-vis de la maladie (passivité) ; modalités de prise des médicaments ; observance.</td></tr>\n          <tr><td><span class=\"kw-def\">Analyse de la demande</span></td><td>Attentes du patient (faisabilité, reformulation) ; objectifs partagés entre le patient et le médecin.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout\">📌 L'entretien ne se limite pas à la douleur « physique » : il explore systématiquement <span class=\"kw-clinique\">les</span> dimensions <strong>psychologique</strong>, <strong>sociale</strong> et <strong>professionnelle</strong>, déterminantes dans la chronicisation.</div>","frequence":3},{"id":"134-4","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître une douleur aiguë et chronique chez l’adulte","contenu":"<p>La distinction <span class=\"kw-def\">douleur aiguë</span> / <span class=\"kw-def\">douleur chronique</span> ne repose pas seulement sur la durée : elle oppose deux logiques entièrement différentes.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Critère</th><th>Douleur aiguë</th><th>Douleur chronique</th></tr></thead>\n        <tbody>\n          <tr><td>Durée</td><td><span class=\"kw-chiffre\">&lt; 3 mois</span></td><td><span class=\"kw-chiffre\">&gt; 3 mois</span> (ou <span class=\"kw-chiffre\">&gt; 2 mois</span> pour la douleur chronique post-opératoire sans complication)</td></tr>\n          <tr><td>Finalité <span class=\"kw-ttt\">biologique</span></td><td><strong>Utile</strong>, protectrice, <span class=\"kw-def\">signal d'alarme</span></td><td><strong>Inutile</strong>, destructrice, <span class=\"kw-alerte\">maladie à part entière</span> avec retentissement sur la qualité de vie</td></tr>\n          <tr><td>Mécanisme générateur</td><td><strong>Unifactoriel</strong> : souvent nociceptif</td><td><strong>Plurifactoriel</strong> ; persiste malgré un traitement étiologique bien conduit</td></tr>\n          <tr><td>Composante affective</td><td><span class=\"kw-clinique\">Anxiété</span></td><td><span class=\"kw-clinique\">Dépression</span> ; syndromes anxio-dépressifs réactionnels fréquents → <span class=\"kw-alerte\">cercle vicieux</span></td></tr>\n          <tr><td>Comportement</td><td>Réactionnel</td><td>Appris, conditionné, renforcé</td></tr>\n          <tr><td>Approche thérapeutique</td><td>Médicale classique</td><td>Pluridimensionnelle « <strong>somato-psycho-social</strong> »</td></tr>\n          <tr><td>Objectif thérapeutique</td><td><strong>Curatif</strong> (modèle médical)</td><td><strong>Réadaptatif</strong> bio-psycho-social (gestion du handicap)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout warning\">⚠️ <strong>À retenir.</strong> Dans la douleur chronique, l'objectif n'est <span class=\"kw-alerte\">plus curatif mais réadaptatif</span> : la douleur persiste malgré un traitement étiologique bien conduit, et c'est le retentissement (handicap, sommeil, humeur) qui devient la cible.</div>","frequence":0},{"id":"134-5","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie des douleurs aiguës en ville et à l’hôpital, des douleurs chroniques","contenu":"<p>La douleur est un <strong>motif majeur de recours aux soins</strong>. La douleur aiguë domine en ville comme à l'hôpital ; la douleur chronique constitue un problème de santé publique, <span class=\"kw-alerte\">sous-évalué et sous-traité</span>.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Type de douleur</th><th><span class=\"kw-def\">Prévalence</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Douleur aiguë</span></td><td><span class=\"kw-chiffre\">2/3</span> des consultations</td></tr>\n          <tr><td><span class=\"kw-def\">Douleur chronique</span> (population générale)</td><td><span class=\"kw-chiffre\">20 à 50 %</span> de la population (<span class=\"kw-chiffre\">≈ 30 %</span> selon <span class=\"kw-clinique\">les</span> données d'anesthésie-<span class=\"kw-alerte\">réanimation</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Douleur du cancer</span></td><td><span class=\"kw-chiffre\">57 %</span> des patients atteints d'un cancer sont douloureux</td></tr>\n          <tr><td><span class=\"kw-def\">Douleur neuropathique</span></td><td><span class=\"kw-chiffre\">≈ 7 %</span> de la population adulte (soit <span class=\"kw-chiffre\">1/4</span> des douloureux chroniques)</td></tr>\n          <tr><td><span class=\"kw-def\">Douleur du sujet âgé</span></td><td><span class=\"kw-chiffre\">52 %</span> des patients de <span class=\"kw-chiffre\">&gt; 75 ans</span> ont une douleur chronique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout\">📌 Repère pédiatrique : on parle de douleur chronique chez l'enfant dès <span class=\"kw-chiffre\">&gt; 15 jours/mois</span> pendant <span class=\"kw-chiffre\">&gt; 3 mois</span>, ou dès que la durée dépasse l'<span class=\"kw-clinique\">évolution</span> attendue.</div>","frequence":0},{"id":"134-6","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître et évaluer une douleur aiguë et chronique chez l’adulte","contenu":"<p>L'évaluation d'une douleur croise deux dimensions : <strong>qualitative</strong> (quel mécanisme ?) et <strong>quantitative</strong> (quelle intensité ?).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Dimension qualitative — orienter le mécanisme</h4>\n      <ul>\n        <li><span class=\"kw-def\">Douleur neuropathique</span> — à rechercher <strong>impérativement</strong> par le questionnaire <span class=\"kw-bio\">DN4</span>.</li>\n        <li><span class=\"kw-def\">Douleur nociceptive</span> — retenue en l'absence d'élément neuropathique et de systématisation neurologique.</li>\n        <li><span class=\"kw-def\">Douleur mixte</span> — associe des éléments neuropathiques et nociceptifs.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Dimension quantitative — auto-évaluation (à privilégier)</h4>\n      <p>La douleur étant subjective, l'<strong>auto-évaluation</strong> est la référence chaque fois qu'elle est possible.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Échelle</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">EN</span> — échelle numérique</td><td>Cotation de <span class=\"kw-chiffre\">0 à 10</span> ; mode le plus courant en pratique, <strong>à privilégier</strong>.</td></tr>\n          <tr><td><span class=\"kw-bio\">EVA</span> — échelle visuelle analogique</td><td>Réglette graduée côté soignant, « aucune douleur » / « douleur maximale » côté patient ; utile en recherche et en post-opératoire.</td></tr>\n          <tr><td><span class=\"kw-bio\">EVS</span> — échelle verbale simple</td><td>Qualificatifs (aucune, faible, moyenne, intense, très intense) ; pour <span class=\"kw-clinique\">les</span> patients ne pouvant pas utiliser l'EN ou l'EVA.</td></tr>\n          <tr><td><span class=\"kw-bio\">Échelle des 6 visages</span> (Face Pain Scale)</td><td>Enfant, personne âgée ou patient communicant en difficulté d'abstraction.</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Dimension quantitative — hétéro-évaluation (patient non communicant)</h4>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Échelle</th><th>Indication</th><th>Seuil</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">ALGOPLUS</span></td><td>Douleur <strong>aiguë</strong>, personne âgée dyscommunicante</td><td><span class=\"kw-chiffre\">≥ 2/5</span></td></tr>\n          <tr><td><span class=\"kw-bio\">DOLOPLUS</span></td><td>Douleur <strong>chronique</strong>, personne âgée dyscommunicante</td><td><span class=\"kw-chiffre\">≥ 5/30</span></td></tr>\n          <tr><td><span class=\"kw-bio\">ECPA</span></td><td>Sujet âgé ; évalue la douleur au <strong>repos</strong> et <strong>aux soins</strong></td><td>—</td></tr>\n          <tr><td><span class=\"kw-bio\">EVENDOL</span></td><td>Enfant de <span class=\"kw-chiffre\">&lt; 4-6 ans</span> ou enfant dyscommunicant</td><td>—</td></tr>\n          <tr><td><span class=\"kw-bio\">EDAAP / ESDDA / EDD</span></td><td>Adolescent ou adulte polyhandicapé dyscommunicant</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Évaluation du retentissement de la douleur chronique</h4>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Échelle</th><th>Dimension explorée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">QDSA</span> (version FR du McGill Pain Questionnaire)</td><td>Dimensions <strong>sensorielle</strong> et <strong>affective</strong> (qualificatifs de la douleur).</td></tr>\n          <tr><td><span class=\"kw-bio\">HADs</span></td><td>Composante <span class=\"kw-clinique\">anxieuse</span> et <span class=\"kw-clinique\">dépressive</span> du douloureux chronique.</td></tr>\n          <tr><td><span class=\"kw-bio\">QCD</span> (questionnaire concis de la douleur)</td><td>Retentissement <strong>comportemental</strong> : activité, humeur, marche, travail, sommeil, relations.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout warning\">⚠️ <strong>Piège classique.</strong> Pour le <span class=\"kw-def\">suivi</span>, toujours <span class=\"kw-alerte\">utiliser la même échelle</span> : <span class=\"kw-clinique\">les</span> échelles ne sont pas équivalentes entre elles et leurs scores ne se comparent pas.</div>","frequence":5},{"id":"134-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une douleur par excès de nociception","contenu":"<p>La <span class=\"kw-def\">douleur par excès de nociception</span> est liée à l'<strong>activation des nocicepteurs périphériques</strong> par une <span class=\"kw-clinique\">lésion</span> tissulaire locale : c'est le fonctionnement <strong>normal</strong> du système nociceptif.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Mécanisme</h4>\n      <p>L'activation des nocicepteurs se fait soit <strong>directement</strong> par la <span class=\"kw-clinique\">lésion</span> tissulaire, soit par <strong>sensibilisation</strong> : l'inflammation (prostaglandines, leucotriènes, histamine) abaisse le seuil d'activation → <span class=\"kw-alerte\">hyperalgésie</span>, voire allodynie.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Situations cliniques fréquentes</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Péri-opératoire</span> — douleur per-opératoire et post-opératoire immédiate.</li>\n        <li><span class=\"kw-etio\">Inflammation</span> — <span class=\"kw-clinique\">colique néphrétique</span>, <span class=\"kw-clinique\">poussée</span> d'arthrite (<span class=\"kw-clinique\">PR</span>, goutte, chondrocalcinose, arthrite infectieuse).</li>\n        <li><span class=\"kw-etio\">Gestes et soins</span> — pansements, ponctions, mobilisations, rééducation.</li>\n        <li><span class=\"kw-etio\">Post-traumatique</span> et douleurs du cancer (souvent mixtes).</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Clinique</h4>\n      <p>Douleurs généralement <strong>aiguës</strong> et intenses, vocabulaire descriptif <strong>pauvre et peu métaphorique</strong> (à l'inverse des douleurs neuropathiques), <span class=\"kw-clinique\">hyperalgésie</span> au premier plan, examen neurologique <strong>normal</strong>, rythme <strong>mécanique</strong> ou <strong><span class=\"kw-etio\">inflammatoire</span></strong>. Évaluation de l'intensité par <span class=\"kw-bio\">EN</span> ou <span class=\"kw-bio\">EVA</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Les</span> <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>rands cadres de douleur — tableau pivot</h4>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Caractéristique</th><th>Nociceptive</th><th>Neuropathique</th><th>Nociplastique</th></tr></thead>\n        <tbody>\n          <tr><td>Origine</td><td>Nocicepteur</td><td><span class=\"kw-clinique\">Lésion</span> du SNC ou SNP</td><td>Anomalie du traitement de la douleur (sensibilisation centrale)</td></tr>\n          <tr><td>Caractéristiques</td><td>Pulsatile, lancinante</td><td><span class=\"kw-clinique\">Brûlure</span>, <span class=\"kw-clinique\">décharges électriques</span>, picotements</td><td><strong>Diffuse</strong>, non systématisée</td></tr>\n          <tr><td>Topographie</td><td><strong>Locorégionale</strong>, site de l'agression</td><td>Systématisée (territoire neurologique)</td><td><strong>Diffuse</strong> ou centrée sur un organe</td></tr>\n          <tr><td>Rythmicité</td><td>Horaire <strong>mécanique</strong> ou <strong><span class=\"kw-etio\">inflammatoire</span></strong></td><td>Spontanée ou déclenchée</td><td><strong>Constante</strong>, avec poussées</td></tr>\n          <tr><td>Examen neurologique</td><td><strong>Normal</strong></td><td>Troubles sensitifs, hypo/hyperalgésie, allodynie</td><td><strong>Normal</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Évolution</span></td><td>Aiguë ou chronique</td><td><strong>Chronique</strong></td><td><strong>Chronique</strong></td></tr>\n          <tr><td>Traitement</td><td><span class=\"kw-ttt\">Antalgiques</span> + traitement de la cause</td><td><span class=\"kw-ttt\">Antiépileptiques</span>, <span class=\"kw-ttt\">antidépresseurs</span> ; approche biopsychosociale</td><td>Prise en charge globale, modulateurs de la douleur</td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout warning\">⚠️ <strong>Piège thérapeutique.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-ci\">paliers OMS</span> sont validés pour la <strong>douleur du cancer</strong> : ne pas s'y référer pour les douleurs non cancéreuses. Les <span class=\"kw-ci\">antidépresseurs et antiépileptiques</span> sont peu efficaces dans la douleur nociceptive pure et n'y ont pas d'indication.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 135 — <span class=\"kw-ttt\">Antalgique</span></em></p>","frequence":1},{"id":"134-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une douleur neuropathique","contenu":"<p>La <span class=\"kw-def\">douleur neuropathique</span> est une douleur secondaire à une <strong><span class=\"kw-clinique\">lésion</span> ou une maladie du système somatosensoriel</strong>, périphérique ou centrale. Elle touche <span class=\"kw-chiffre\">≈ 7 %</span> de la population adulte.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étiologies</h4>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Périphériques</th><th>Centrales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-etio\">Radiculopathies</span> (hernie discale, canal lombaire étroit) — <span class=\"kw-clinique\">les</span> plus fréquentes<br>\n              <span class=\"kw-etio\">Lésions nerveuses post-opératoires ou post-traumatiques</span> (post-thoracotomie, post-mastectomie)<br>\n              <span class=\"kw-etio\">Syndromes canalaires</span> (canal carpien)<br>\n              <span class=\"kw-etio\">Neuropathies diabétiques et non diabétiques</span> (chimio-induites, <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">VIH</span>)<br>\n              <span class=\"kw-etio\">Douleurs post-zostériennes</span> ; <span class=\"kw-etio\">plexite radique</span><br>\n              <span class=\"kw-etio\">Envahissement ou compression nerveuse tumorale</span>\n            </td>\n            <td>\n              <span class=\"kw-etio\">Accident vasculaire cérébral</span><br>\n              <span class=\"kw-etio\">Lésions médullaires traumatiques</span><br>\n              <span class=\"kw-etio\">Sclérose en plaques</span><br>\n              <span class=\"kw-etio\">Syringomyélie</span><br>\n              <span class=\"kw-etio\">Traumatisme crânien grave</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Clinique</h4>\n      <ul>\n        <li>Descripteurs caractéristiques : <span class=\"kw-clinique\">brûlure</span>, <span class=\"kw-clinique\">décharges électriques</span>, <span class=\"kw-clinique\">froid douloureux</span>.</li>\n        <li><span class=\"kw-clinique\">Paresthésies / dysesthésies</span> dans la zone douloureuse : fourmillements, picotements, démangeaisons, engourdissement.</li>\n        <li>Composante continue ou paroxystique, spontanée ou déclenchée.</li>\n        <li>Topographie <strong>systématisée</strong> à un territoire neuro-anatomique.</li>\n        <li>Signes <strong>négatifs</strong> (<span class=\"kw-clinique\">hypoesthésie</span>, <span class=\"kw-clinique\">déficit sensitif</span>) et <strong>positifs</strong> (<span class=\"kw-clinique\">allodynie</span>, <span class=\"kw-clinique\">hyperalgésie</span> au froid ou à la piqûre).</li>\n      </ul>\n      <div class=\"obj-callout\">📌 <strong>Diagnostic.</strong> Le questionnaire <span class=\"kw-bio\">DN4</span> oriente vers une douleur neuropathique au seuil de <span class=\"kw-chiffre\">≥ 4/10</span> ; sa version en interrogatoire seul a un seuil de <span class=\"kw-chiffre\">≥ 3/7</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 135 — <span class=\"kw-ttt\">Antalgique</span></em></p>","frequence":3},{"id":"134-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une douleur du cancer","contenu":"<p><span class=\"kw-chiffre\">57 %</span> des patients atteints d'un cancer sont douloureux ; la douleur reste fréquemment <span class=\"kw-alerte\">sous-traitée</span>. <span class=\"kw-clinique\">Les</span> douleurs cancéreuses relèvent de <strong>plusieurs mécanismes</strong> (nociceptif, neuropathique, mixte, nociplastique) et sont liées :</p>\n      <ul>\n        <li>à la <span class=\"kw-etio\">tumeur</span> elle-même (compression, <span class=\"kw-bio\">envahissement</span>) ;</li>\n        <li>au <span class=\"kw-etio\">traitement</span> (<span class=\"kw-ttt\">chirurgie</span>, <span class=\"kw-ttt\">chimiothérapie</span>, radiothérapie, hormonothérapie).</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Reconnaître <span class=\"kw-clinique\">les</span> types de douleur selon l'<span class=\"kw-clinique\">évolution</span></h4>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Type</th><th>Définition</th><th>Logique de traitement</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Douleur de fond</span></td><td>Continue, souvent permanente ; nociceptive ou neuropathique.</td><td>Traitement de fond à <strong>libération prolongée</strong> (<span class=\"kw-ttt\">morphine LP</span>, <span class=\"kw-ttt\">oxycodone LP</span>).</td></tr>\n          <tr><td><span class=\"kw-def\">Accès douloureux</span> « classiques »</td><td>Majoration modérée à sévère sur quelques dizaines de minutes à quelques heures.</td><td><span class=\"kw-ttt\">Antalgiques</span> à <strong>libération immédiate</strong> ou interdoses (<span class=\"kw-ttt\">morphine LI</span>, <span class=\"kw-ttt\">oxycodone LI</span>).</td></tr>\n          <tr><td><span class=\"kw-def\">Accès douloureux paroxystique</span> (ADP)</td><td>Exacerbation <strong>brutale</strong> et brève (<span class=\"kw-chiffre\">&lt; 1 h</span>), spontanée ou provoquée.</td><td>Traitement à délai d'action <strong>très rapide</strong> (<span class=\"kw-ttt\">fentanyl</span> transmuqueux ou nasal).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout\">📌 <strong>Un traitement <span class=\"kw-ttt\">antalgique</span> efficace</strong> = douleur de fond absente ou faible, <strong>respect du sommeil</strong>, <span class=\"kw-chiffre\">&lt; 4</span> accès douloureux/jour avec efficacité <span class=\"kw-chiffre\">&gt; 50 %</span>, activités habituelles préservées, effets indésirables mineurs.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 135 — <span class=\"kw-ttt\">Antalgique</span> · 139 — Soins palliatifs - repères cliniques - organisation hospitalière et ambulatoire · 141 — Soins palliatifs 3 - sédation - fin de vie</em></p>","frequence":3},{"id":"134-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une douleur du sujet âgé","contenu":"<p>La douleur du sujet âgé est <strong>fréquente</strong> (<span class=\"kw-chiffre\">52 %</span> des <span class=\"kw-chiffre\">&gt; 75 ans</span> ont une douleur chronique) mais <span class=\"kw-alerte\">insuffisamment évaluée et traitée</span>, en particulier en EHPAD et chez <span class=\"kw-clinique\">les</span> patients ayant des <strong>troubles de la communication verbale</strong>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Effet de l'âge</h4>\n      <p>Le vieillissement entraîne globalement une <strong>augmentation de la sensibilité à la douleur</strong>, malgré deux phénomènes contradictoires : élévation du seuil de détection (démyélinisation des fibres) et baisse du seuil de tolérance (sensibilisation centrale). La pharmacocinétique est modifiée — l'<span class=\"kw-bio\">excrétion rénale</span> est l'étape la plus affectée → <strong><span class=\"kw-ttt\">réduction</span> des posologies</strong> d'opioïdes recommandée.</p>\n      <div class=\"obj-callout danger\">⚠️ <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Chez un patient ayant des <span class=\"kw-alerte\">troubles neurocognitifs</span>, toute <span class=\"kw-alerte\">modification du comportement</span> (agitation, agressivité, refus de soins, repli, refus alimentaire) doit faire <strong>rechercher une douleur</strong>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Évaluation</h4>\n      <ul>\n        <li><strong>Auto-évaluation</strong> tant qu'elle est fiable : l'<span class=\"kw-bio\">EVS</span> est l'<strong>échelle de référence</strong> chez la personne âgée (simple, sans capacité d'abstraction requise) ; EN, EVA, échelle faciale possibles.</li>\n        <li><strong>Hétéro-évaluation</strong> si troubles cognitifs ou de la communication : <span class=\"kw-bio\">Algoplus</span> (douleur aiguë, seuil <span class=\"kw-chiffre\">≥ 2/5</span>), <span class=\"kw-bio\">Doloplus</span> (douleur chronique), <span class=\"kw-bio\">ECPA</span>.</li>\n        <li>Composante neuropathique fréquente chez le sujet âgé → questionnaire <span class=\"kw-bio\">DN4</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 138 — Douleur chez la personne vulnérable</em></p>","frequence":0},{"id":"134-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une douleur nociplastique : fibromyalgie, syndrome de l’instestin irritable","contenu":"<p>La <span class=\"kw-def\">douleur nociplastique</span> résulte d'une <strong>perturbation du fonctionnement du système de la douleur</strong>, <span class=\"kw-alerte\">sans activation des nocicepteurs ni lésion neurologique</span>. Deux mécanismes :</p>\n      <ul>\n        <li><span class=\"kw-def\">Hypersensibilité centrale</span> ;</li>\n        <li><span class=\"kw-def\">Perte de l'inhibition descendante</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Clinique</h4>\n      <ul>\n        <li>Début <strong>non identifié</strong> par le patient ; rythmicité <strong>constante avec poussées</strong>.</li>\n        <li>Topographie <strong>diffuse</strong> (fibromyalgie) ou <strong>centrée sur un organe</strong> (colopathie, cystalgie, précordialgies).</li>\n        <li>Examen neurologique <strong>normal</strong>.</li>\n        <li>Signes associés : <span class=\"kw-clinique\">troubles du sommeil</span>, <span class=\"kw-clinique\">fatigue</span>, troubles de concentration, <span class=\"kw-clinique\">anxiété</span>, <span class=\"kw-clinique\">dépression</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Exemples</h4>\n      <p><span class=\"kw-etio\">Fibromyalgie</span>, <span class=\"kw-etio\">syndrome du côlon irritable</span>, <span class=\"kw-etio\">céphalée de tension</span>, <span class=\"kw-etio\">cystalgies à urines claires</span> (cystites interstitielles), <span class=\"kw-etio\">douleurs pelviennes</span>, <span class=\"kw-etio\">vulvodynies</span>, <span class=\"kw-etio\">coccygodynies</span>, <span class=\"kw-etio\">glossodynies</span>, douleurs de l'articulation temporo-mandibulaire, rachialgies idiopathiques.</p>\n      <div class=\"obj-callout warning\">⚠️ <strong>Piège majeur.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">comorbidités</span> psychiatriques (troubles anxieux, <span class=\"kw-def\">dépression</span>) sont fréquentes, mais la douleur nociplastique <span class=\"kw-alerte\">n'est PAS l'expression somatique d'un trouble psychiatrique</span> — c'est une dysfonction réelle du traitement de la douleur.</div>","frequence":1}],"astuces":[],"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-11-6.php","label":"lecofer.org"},{"href":"https://www.cen-neurologie.fr/second-cycle/douleur","label":"cen-neurologie.fr"},{"href":"https://www.sfetd-douleur.org/wp-content/uploads/2019/08/dn4ok.pdf","label":"sfetd-douleur.org"},{"href":"https://www.chu-montpellier.fr/fileadmin/medias/Pages/patients-visiteurs/Engagements-du-CHU/CLUD/Echelles/echelle-EVA.pdf","label":"chu-montpellier.fr"},{"href":"http://www.cnrd.fr","label":"www.cnrd.fr"},{"href":"https://www.antalvite.fr/wp-content/uploads/2021/08/QDSA-1.pdf","label":"antalvite.fr"},{"href":"https://www.has-sante.fr/upload/docs/application/pdf/2014-11/outil__echelle_had.pdf","label":"has-sante.fr"},{"href":"https://www.interclud-occitanie.fr/DesktopModules/NBright/NBrightMod/XmlConnector.ashx","label":"interclud-occitanie.fr"}],"cards":[{"i":"2c75d006fa85","n":134,"o":"134-1","u":"Définition","t":"Connaître la définition OMS de la douleur","q":"Selon l'OMS et l'IASP, quelle est la définition précise de la douleur ?","a":"<p>La douleur est définie comme une « <strong>expérience désagréable, sensorielle et émotionnelle, associée ou ressemblant à ce qui est associé à une lésion tissulaire réelle ou potentielle</strong> ».</p>"},{"i":"6adf39ee4e70","n":134,"o":"134-1","u":"Définition","t":"Connaître la définition OMS de la douleur","q":"Qu'est-ce qui différencie la douleur de la nociception ?","a":"<p>La <strong>nociception</strong> est le système physiologique de détection des stimulations menaçant l'intégrité de l'organisme. La <strong>douleur</strong>, quant à elle, est une expérience sensorielle et émotionnelle, et ne se résume pas à l'activité des neurones sensoriels. On peut avoir une lésion tissulaire sans douleur, ou une douleur sans cause nociceptive identifiable.</p>"},{"i":"c6387e59a315","n":134,"o":"134-1","u":"Définition","t":"Connaître la définition OMS de la douleur","q":"Quels sont les facteurs influençant l'expérience personnelle de la douleur, selon la définition de l'OMS ?","a":"<p>L'expérience de la douleur est toujours personnelle et est influencée à des degrés divers par des facteurs <strong>biologiques, psychologiques et sociaux</strong>.</p>"},{"i":"3250a076aee3","n":134,"o":"134-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du sujet âgé","q":"Quel type de douleur est fréquent chez le sujet âgé et quel outil est recommandé pour l'évaluer ?","a":"<p>La <strong>composante neuropathique</strong> est fréquente chez le sujet âgé. Le <strong>questionnaire DN4</strong> est recommandé pour l'évaluer.</p>"},{"i":"4e55a477c96e","n":134,"o":"134-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du sujet âgé","q":"Quelles sont les échelles d'hétéro-évaluation de la douleur recommandées chez le sujet âgé en cas de troubles cognitifs ou de communication ?","a":"<p>En cas de troubles cognitifs ou de communication, l'hétéro-évaluation est nécessaire. Les échelles recommandées sont :</p><ul><li><strong>Algoplus</strong> pour la douleur aiguë (seuil ≥ 2/5)</li><li><strong>Doloplus</strong> pour la douleur chronique</li><li><strong>ECPA</strong> (Évaluation Comportementale de la Personne Âgée)</li></ul>"},{"i":"a9e1508505f1","n":134,"o":"134-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du sujet âgé","q":"Quelles sont les échelles d'auto-évaluation de la douleur recommandées chez le sujet âgé ?","a":"<p>Tant que l'auto-évaluation est fiable, l'<strong>EVS (Échelle Verbale Simple)</strong> est l'échelle de référence chez la personne âgée car elle est simple et ne requiert pas de capacités d'abstraction. L'EN (Échelle Numérique), l'EVA (Échelle Visuelle Analogique) et les échelles faciales sont également possibles.</p>"},{"i":"be7f37876867","n":134,"o":"134-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du sujet âgé","q":"Quels sont les effets du vieillissement sur la perception de la douleur et la pharmacocinétique des antalgiques ?","a":"<p>Le vieillissement entraîne globalement une <strong>augmentation de la sensibilité à la douleur</strong>. On observe une <strong>élévation du seuil de détection</strong> (démyélinisation des fibres) et une <strong>baisse du seuil de tolérance</strong> (sensibilisation centrale).</p><p>Sur le plan pharmacocinétique, l'<strong>excrétion rénale est l'étape la plus affectée</strong>, ce qui impose une <strong>réduction des posologies d'opioïdes</strong>.</p>"},{"i":"ecb70ca87cf3","n":134,"o":"134-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du sujet âgé","q":"Quelle est la fréquence de la douleur chez le sujet âgé et quelles en sont les conséquences en termes de prise en charge ?","a":"<p>La douleur est <strong>fréquente</strong> chez le sujet âgé, affectant <strong>52 % des plus de 75 ans</strong> avec une douleur chronique. Elle est cependant <strong>insuffisamment évaluée et traitée</strong>, notamment en EHPAD et chez les patients ayant des troubles de la communication verbale.</p>"},{"i":"f1bb0a16cfbd","n":134,"o":"134-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du sujet âgé","q":"Quel \"drapeau rouge\" doit alerter sur une potentielle douleur chez un patient âgé ayant des troubles neurocognitifs ?","a":"<p>Chez un patient ayant des troubles neurocognitifs, <strong>toute modification du comportement</strong> doit faire rechercher une douleur. Cela inclut :</p><ul><li>Agitation</li><li>Agressivité</li><li>Refus de soins</li><li>Repli</li><li>Refus alimentaire</li></ul>"},{"i":"23f4ac6d9f3c","n":134,"o":"134-11","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur nociplastique : fibromyalgie, syndrome de l’instestin irritable","q":"Quels sont les signes cliniques caractéristiques orientant vers une douleur nociplastique (fibromyalgie, syndrome de l'intestin irritable) ?","a":"<ul><li>Un <strong>début non identifié</strong> par le patient.</li><li>Une <strong>rythmicité constante avec poussées</strong>.</li><li>Une <strong>topographie diffuse</strong> (comme dans la fibromyalgie) ou <strong>centrée sur un organe</strong> (comme la colopathie).</li><li>Un <strong>examen neurologique normal</strong>.</li><li>Des signes associés fréquents : <strong>troubles du sommeil</strong>, <strong>fatigue</strong>, <strong>troubles de concentration</strong>, <strong>anxiété</strong>, <strong>dépression</strong>.</li></ul>"},{"i":"67f499e02494","n":134,"o":"134-11","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur nociplastique : fibromyalgie, syndrome de l’instestin irritable","q":"Quelle est la physiopathologie principale de la douleur nociplastique dans le cadre de la fibromyalgie ou du syndrome de l'intestin irritable ?","a":"<p>La douleur nociplastique résulte d'une <strong>perturbation du fonctionnement du système de la douleur</strong>. Elle se caractérise par deux mécanismes principaux : une <strong>hypersensibilité centrale</strong> et une <strong>perte de l'inhibition descendante</strong>, sans activation des nocicepteurs ni lésion neurologique.</p>"},{"i":"75b9a216cf22","n":134,"o":"134-11","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur nociplastique : fibromyalgie, syndrome de l’instestin irritable","q":"Comment différencier une douleur nociplastique d'une expression somatique d'un trouble psychiatrique chez un patient présentant des douleurs de type fibromyalgie ou syndrome de l'intestin irritable ?","a":"<p>Il est crucial de comprendre que la douleur nociplastique <strong>n'est PAS l'expression somatique d'un trouble psychiatrique</strong>. Bien que les comorbidités psychiatriques (troubles anxieux, dépression) soient fréquentes chez ces patients, la douleur nociplastique est une <strong>dysfonction réelle du traitement de la douleur</strong> par le système nerveux central et non une manifestation d'un trouble psychique.</p>"},{"i":"6033a893695d","n":134,"o":"134-3","u":"Diagnostic positif","t":"Connaître les éléments del’interrogatoire d’un patient douloureux","q":"Quels sont les axes principaux à explorer lors de l'interrogatoire d'un patient présentant une douleur chronique, concernant l'histoire de sa douleur ?","a":"<ul><li><strong>Ancienneté de la douleur</strong> : mode de début, circonstances exactes, description initiale, prise en charge immédiate, diagnostic initial.</li><li><strong>Profil évolutif</strong> : installation de l'état douloureux persistant, profil (permanente, récurrente, intermittente), degré de retentissement.</li><li><strong>Description de la douleur actuelle</strong> : topographie, type de sensation (brûlure, décharge électrique), intensité, facteurs d'aggravation et de soulagement, retentissement.</li></ul>"},{"i":"70dec2900295","n":134,"o":"134-3","u":"Diagnostic positif","t":"Connaître les éléments del’interrogatoire d’un patient douloureux","q":"Quelle est l'importance de l'interrogatoire dans l'évaluation d'une douleur chronique ?","a":"<p>L'interrogatoire est un élément essentiel de l'évaluation, s'appuyant sur une <strong>grille d'entretien semi-structuré en 9 axes</strong>. Il permet d'appréhender le retentissement de la douleur (anxiété, dépression, troubles du sommeil, incapacité fonctionnelle et professionnelle) qui en est le fil rouge.</p>"},{"i":"9008e0a15876","n":134,"o":"134-3","u":"Diagnostic positif","t":"Connaître les éléments del’interrogatoire d’un patient douloureux","q":"Quels domaines, au-delà de la douleur elle-même, doivent être systématiquement explorés lors de l'interrogatoire d'un patient douloureux chronique ?","a":"<ul><li><strong>Traitements</strong> : médicamenteux et non médicamenteux (antérieurs et actuels), doses, modes d'administration, effets bénéfiques, effets indésirables, raisons d'abandon.</li><li><strong>Antécédents</strong> : familiaux et personnels (médicaux, chirurgicaux, obstétricaux, psychiatriques), expériences douloureuses antérieures.</li><li><strong>Contexte familial, psychosocial, médico-légal</strong> : situation familiale et sociale, statut professionnel, indemnisations.</li><li><strong>Facteurs cognitifs</strong> : représentation de la maladie, interprétation des avis médicaux.</li><li><strong>Facteurs comportementaux</strong> : attitude vis-à-vis de la maladie, modalités de prise des médicaments, observance.</li><li><strong>Analyse de la demande</strong> : attentes du patient, objectifs partagés.</li></ul>"},{"i":"0b4bd4792420","n":134,"o":"134-4","u":"Diagnostic positif","t":"Reconnaître une douleur aiguë et chronique chez l’adulte","q":"Quelle est la durée qui distingue classiquement une douleur aiguë d'une douleur chronique ?","a":"<p>La douleur aiguë est caractérisée par une durée <strong>inférieure à 3 mois</strong>. La douleur chronique, quant à elle, dure <strong>plus de 3 mois</strong> (ou > 2 mois pour une douleur chronique post-opératoire sans complication).</p>"},{"i":"4ab6894d75a2","n":134,"o":"134-4","u":"Diagnostic positif","t":"Reconnaître une douleur aiguë et chronique chez l’adulte","q":"Quelle est la principale différence dans l'approche thérapeutique entre une douleur aiguë et une douleur chronique ?","a":"<ul><li>L'approche thérapeutique de la douleur aiguë est <strong>médicale classique</strong> avec un objectif <strong>curatif</strong>.</li><li>L'approche thérapeutique de la douleur chronique est <strong>pluridimensionnelle et \"somato-psycho-sociale\"</strong>, avec un objectif <strong>réadaptatif bio-psycho-social</strong> (gestion du handicap), car la douleur peut persister malgré un traitement étiologique bien conduit.</li></ul>"},{"i":"d2020dcb5bf3","n":134,"o":"134-4","u":"Diagnostic positif","t":"Reconnaître une douleur aiguë et chronique chez l’adulte","q":"Comment les composantes affectives diffèrent-elles entre la douleur aiguë et la douleur chronique ?","a":"<ul><li>La douleur aiguë est principalement associée à une composante affective d'<strong>anxiété</strong>.</li><li>La douleur chronique est souvent associée à une <strong>dépression</strong> et à des <strong>syndromes anxio-dépressifs réactionnels</strong>, pouvant créer un cercle vicieux.</li></ul>"},{"i":"e53c8e4112c8","n":134,"o":"134-4","u":"Diagnostic positif","t":"Reconnaître une douleur aiguë et chronique chez l’adulte","q":"Décrivez la finalité biologique de la douleur aiguë et de la douleur chronique.","a":"<ul><li>La douleur aiguë est <strong>utile et protectrice</strong>, agissant comme un signal d'alarme.</li><li>La douleur chronique est <strong>inutile et destructrice</strong> ; elle est considérée comme une maladie à part entière avec un retentissement sur la qualité de vie.</li></ul>"},{"i":"06585c2e8f56","n":134,"o":"134-6","u":"Diagnostic positif","t":"Reconnaître et évaluer une douleur aiguë et chronique chez l’adulte","q":"Quelles sont les principales échelles d'auto-évaluation de la douleur chez l'adulte, et dans quelles situations sont-elles utilisées ?","a":"<p>L'auto-évaluation est la référence pour quantifier la douleur lorsque le patient est communicant :</p><ul><li>L'<strong>Échelle Numérique (EN)</strong> : cotation de <strong>0 à 10</strong>, mode le plus courant et à privilégier.</li><li>L'<strong>Échelle Visuelle Analogique (EVA)</strong> : réglette graduée, utile en recherche et en post-opératoire.</li><li>L'<strong>Échelle Verbale Simple (EVS)</strong> : utilise des qualificatifs (aucune, faible, moyenne, intense, très intense), pour les patients ne pouvant pas utiliser l'EN ou l'EVA.</li><li>L'<strong>Échelle des 6 visages (Face Pain Scale)</strong> : pour l'enfant, la personne âgée ou le patient ayant des difficultés d'abstraction.</li></ul>"},{"i":"3958956f21dd","n":134,"o":"134-6","u":"Diagnostic positif","t":"Reconnaître et évaluer une douleur aiguë et chronique chez l’adulte","q":"Quels sont les outils d'évaluation du retentissement de la douleur chronique chez l'adulte, et quelles dimensions explorent-ils ?","a":"<p>L'évaluation du retentissement de la douleur chronique utilise différents questionnaires :</p><ul><li>Le <strong>QDSA</strong> (version FR du McGill Pain Questionnaire) : explore les dimensions <strong>sensorielle et affective</strong> de la douleur.</li><li>Le <strong>HADs</strong> : évalue la <strong>composante anxieuse et dépressive</strong> chez le douloureux chronique.</li><li>Le <strong>QCD</strong> (questionnaire concis de la douleur) : évalue le <strong>retentissement comportemental</strong> (activité, humeur, marche, travail, sommeil, relations).</li></ul>"},{"i":"89657b99d3cd","n":134,"o":"134-6","u":"Diagnostic positif","t":"Reconnaître et évaluer une douleur aiguë et chronique chez l’adulte","q":"Quelles sont les échelles d'hétéro-évaluation de la douleur couramment utilisées chez l'adulte non communicant, et dans quelles situations sont-elles indiquées ?","a":"<p>Pour la personne non communicante, la douleur est évaluée par hétéro-évaluation :</p><ul><li><strong>ALGOPLUS</strong> : pour la douleur aiguë chez la personne âgée dyscommunicante (seuil <strong>≥ 2/5</strong>).</li><li><strong>DOLOPLUS</strong> : pour la douleur chronique chez la personne âgée dyscommunicante (seuil <strong>≥ 5/30</strong>).</li><li><strong>ECPA</strong> : chez le sujet âgé, évalue la douleur au repos et aux soins.</li><li><strong>EVENDOL</strong> : chez l'enfant de < 4-6 ans ou enfant dyscommunicant.</li><li><strong>EDAAP / ESDDA / EDD</strong> : pour l'adolescent ou l'adulte polyhandicapé dyscommunicant.</li></ul>"},{"i":"996e1547c19c","n":134,"o":"134-6","u":"Diagnostic positif","t":"Reconnaître et évaluer une douleur aiguë et chronique chez l’adulte","q":"Quel piège classique faut-il éviter lors du suivi de la douleur chez un patient ?","a":"<p>Pour le suivi de la douleur, il est important de <strong>toujours utiliser la même échelle</strong>. Les échelles ne sont pas équivalentes entre elles et leurs scores ne se comparent pas.</p>"},{"i":"e0ca284a8ac9","n":134,"o":"134-6","u":"Diagnostic positif","t":"Reconnaître et évaluer une douleur aiguë et chronique chez l’adulte","q":"Comment doit être évaluée la dimension qualitative de la douleur chez l'adulte, et quels sont les principaux mécanismes à distinguer ?","a":"<p>L'évaluation qualitative de la douleur chez l'adulte cherche à déterminer le mécanisme de la douleur.</p><ul><li>La <strong>douleur neuropathique</strong> doit être recherchée impérativement à l'aide du questionnaire <strong>DN4</strong>.</li><li>La <strong>douleur nociceptive</strong> est retenue en l'absence d'éléments neuropathiques et de systématisation neurologique.</li><li>La <strong>douleur mixte</strong> associe des éléments neuropathiques et nociceptifs.</li></ul>"},{"i":"03524fc5bed7","n":134,"o":"134-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur par excès de nociception","q":"Quelle est la définition d'une douleur par excès de nociception ?","a":"<p>La douleur par excès de nociception est liée à l'<strong>activation des nocicepteurs périphériques</strong> par une <strong>lésion tissulaire locale</strong>. Il s'agit du fonctionnement normal du système nociceptif.</p>"},{"i":"6029b421fdfa","n":134,"o":"134-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur par excès de nociception","q":"Comment évalue-t-on l'intensité d'une douleur par excès de nociception ?","a":"<p>L'intensité d'une douleur par excès de nociception est évaluée à l'aide d'une <strong>Échelle Numérique (EN)</strong> ou d'une <strong>Échelle Visuelle Analogique (EVA)</strong>.</p>"},{"i":"63c9b489c587","n":134,"o":"134-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur par excès de nociception","q":"Quelles sont les principales caractéristiques cliniques d'une douleur par excès de nociception ?","a":"<ul><li>Douleurs généralement <strong>aiguës</strong> et <strong>intenses</strong>.</li><li>Vocabulaire descriptif <strong>pauvre</strong> et peu métaphorique.</li><li><strong>Hyperalgésie</strong> au premier plan.</li><li>Examen neurologique <strong>normal</strong>.</li><li>Rythme <strong>mécanique ou inflammatoire</strong>.</li></ul>"},{"i":"c6e684330ffb","n":134,"o":"134-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur par excès de nociception","q":"Quels sont les cadres cliniques fréquents d'une douleur par excès de nociception ?","a":"<ul><li>Douleurs <strong>péri-opératoires</strong> (per-opératoire et post-opératoire immédiate).</li><li>Douleurs inflammatoires (<strong>colique néphrétique</strong>, poussée d'arthrite : PR, goutte, chondrocalcinose, arthrite infectieuse).</li><li>Douleurs liées aux <strong>gestes et soins</strong> (pansements, ponctions, mobilisations, rééducation).</li><li>Douleurs <strong>post-traumatiques</strong>.</li><li>Douleurs du <strong>cancer</strong> (souvent mixtes).</li></ul>"},{"i":"f7df83f9c7d7","n":134,"o":"134-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur par excès de nociception","q":"Comment les nocicepteurs sont-ils activés dans le cadre d'une douleur par excès de nociception ?","a":"<p>L'activation des nocicepteurs se fait soit <strong>directement par la lésion tissulaire</strong>, soit <strong>par sensibilisation</strong>. L'inflammation (prostaglandines, leucotriènes, histamine) abaisse le seuil d'activation, entraînant une <strong>hyperalgésie</strong> ou une <strong>allodynie</strong>.</p>"},{"i":"1b86930f4082","n":134,"o":"134-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur neuropathique","q":"Quelle est la définition d'une douleur neuropathique ?","a":"<p>Une douleur neuropathique est une douleur secondaire à une <strong>lésion</strong> ou une <strong>maladie du système somatosensoriel</strong>, qu'il soit périphérique ou central.</p>"},{"i":"2dc0268ef734","n":134,"o":"134-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur neuropathique","q":"Quels sont les signes cliniques positifs et négatifs associés à la douleur neuropathique ?","a":"<ul><li><strong>Signes négatifs</strong> : <strong>hypoesthésie</strong> et <strong>déficit sensitif</strong> dans la zone douloureuse.</li><li><strong>Signes positifs</strong> : <strong>allodynie</strong> et <strong>hyperalgésie</strong> (notamment au froid ou à la piqûre).</li><li>Des <strong>paresthésies/dysesthésies</strong> (fourmillements, picotements, démangeaisons, engourdissement) sont également notées dans la zone douloureuse.</li></ul>"},{"i":"5df58d3b767b","n":134,"o":"134-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur neuropathique","q":"Quelles sont les causes périphériques les plus fréquentes de douleur neuropathique ?","a":"<ul><li>Les <strong>radiculopathies</strong> (hernie discale, canal lombaire étroit).</li><li>Les <strong>lésions nerveuses post-opératoires ou post-traumatiques</strong> (post-thoracotomie, post-mastectomie).</li><li>Les <strong>syndromes canalaires</strong> (canal carpien).</li><li>Les <strong>neuropathies diabétiques et non diabétiques</strong> (chimio-induites, alcool, VIH).</li><li>Les <strong>douleurs post-zostériennes</strong> et les <strong>plexites radiques</strong>.</li><li>L'<strong>envahissement ou la compression nerveuse tumorale</strong>.</li></ul>"},{"i":"bcba107f4560","n":134,"o":"134-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur neuropathique","q":"Quels sont les descripteurs caractéristiques de la douleur neuropathique ?","a":"<p>Les patients décrivent typiquement une sensation de <strong>brûlure</strong>, de <strong>décharges électriques</strong> ou de <strong>froid douloureux</strong>.</p>"},{"i":"d2fa1171e112","n":134,"o":"134-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur neuropathique","q":"Quelles sont les causes centrales de douleur neuropathique ?","a":"<ul><li>L'<strong>accident vasculaire cérébral (AVC)</strong>.</li><li>Les <strong>lésions médullaires traumatiques</strong>.</li><li>La <strong>sclérose en plaques</strong>.</li><li>La <strong>syringomyélie</strong>.</li><li>Le <strong>traumatisme crânien grave</strong>.</li></ul>"},{"i":"e33a67575ae3","n":134,"o":"134-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur neuropathique","q":"Quel est l'outil diagnostique clé pour orienter vers une douleur neuropathique et quel est son seuil ?","a":"<p>Le <strong>questionnaire DN4</strong> est un outil diagnostique clé. Une douleur est orientée comme neuropathique pour un seuil de <strong>≥ 4/10</strong>. Pour sa version en interrogatoire seul, le seuil est de <strong>≥ 3/7</strong>.</p>"},{"i":"12fa06a49c2b","n":134,"o":"134-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du cancer","q":"Quels sont les critères d'évaluation d'un traitement antalgique efficace chez un patient douloureux atteint de cancer ?","a":"<ul><li>Douleur de fond <strong>absente ou faible</strong>.</li><li><strong>Respect du sommeil</strong>.</li><li><strong>Moins de 4 accès douloureux/jour</strong> avec une efficacité <strong>supérieure à 50 %</strong>.</li><li>Activités habituelles <strong>préservées</strong>.</li><li>Effets indésirables <strong>mineurs</strong>.</li></ul>"},{"i":"71ab49399e2d","n":134,"o":"134-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du cancer","q":"Comment définir les accès douloureux paroxystiques (ADP) dans le cadre du cancer et quel traitement y est associé ?","a":"<p>Les accès douloureux paroxystiques (ADP) sont des <strong>exacerbations brutales et brèves</strong> (<strong>moins d'une heure</strong>), spontanées ou provoquées. Ils sont traités par des antalgiques à <strong>délai d'action très rapide</strong> (par exemple, <strong>fentanyl transmuqueux</strong> ou <strong>nasal</strong>).</p>"},{"i":"7ad38c3d853f","n":134,"o":"134-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du cancer","q":"Quelles sont les étiologies des douleurs cancéreuses liées directement à la maladie ou à ses traitements ?","a":"<ul><li><strong>Liées à la tumeur elle-même</strong> : compression, envahissement.</li><li><strong>Liées au traitement</strong> : chirurgie, chimiothérapie, radiothérapie, hormonothérapie.</li></ul>"},{"i":"93dc14b70f76","n":134,"o":"134-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du cancer","q":"Quelle est la prévalence de la douleur chez les patients atteints d'un cancer et le problème majeur associé à sa prise en charge ?","a":"<p>La douleur concerne environ <strong>57 %</strong> des patients atteints d'un cancer. Le problème majeur est qu'elle reste <strong>fréquemment sous-traitée</strong>.</p>"},{"i":"d09fc43cbe96","n":134,"o":"134-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du cancer","q":"Quels sont les principaux mécanismes physiopathologiques des douleurs cancéreuses ?","a":"<ul><li><strong>Nociceptif</strong></li><li><strong>Neuropathique</strong></li><li><strong>Mixte</strong></li><li><strong>Nociplastique</strong></li></ul>"},{"i":"fac9c035c4df","n":134,"o":"134-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une douleur du cancer","q":"Qu'est-ce qu'une douleur de fond dans le contexte des douleurs cancéreuses et quel est son principe de traitement ?","a":"<p>Une douleur de fond est une douleur <strong>continue, souvent permanente</strong>, de type nociceptive ou neuropathique. Elle est traitée par un <strong>traitement de fond à libération prolongée</strong> (par exemple, <strong>morphine LP</strong>, <strong>oxycodone LP</strong>).</p>"}]};